import { useState } from "react";

function CampoNome() {
  const [nome, setNome] = useState("");

  return (
    <input
      type="text"
      value={nome}
      onChange={(e) => setNome(e.target.value)}
      placeholder="Seu nome"
    />
  );
}

import { useState } from "react";

type Campo = "nome" | "email" | "mensagem";

function FormularioContato() {
  const [dados, setDados] = useState({
    nome: "",
    email: "",
    mensagem: "",
  });

  function atualizarCampo(campo: Campo, valor: string) {
    setDados({ ...dados, [campo]: valor });
  }

  return (
    <form>
      <input
        value={dados.nome}
        onChange={(e) => atualizarCampo("nome", e.target.value)}
      />
      <input
        value={dados.email}
        onChange={(e) => atualizarCampo("email", e.target.value)}
      />
    </form>
  );
}

import { useState } from "react";

interface Tarefa {
  id: number;
  texto: string;
}

function ListaTarefas() {
  const [tarefas, setTarefas] = useState<Tarefa[]>([]);
  const [texto, setTexto] = useState("");

  function adicionar() {
    if (!texto.trim()) return;          // ignora campo vazio
    const nova = { id: Date.now(), texto: texto.trim() };
    setTarefas((atual) => [...atual, nova]);   // array NOVO
    setTexto("");                       // limpa o campo
  }

  function remover(id: number) {
    setTarefas((atual) => atual.filter((t) => t.id !== id));
  }

  return (
    <div>
      <input value={texto} onChange={(e) => setTexto(e.target.value)} />
      <button onClick={adicionar}>Adicionar</button>
      <ul>
        {tarefas.map((t) => (
          <li key={t.id}>
            {t.texto} <button onClick={() => remover(t.id)}>x</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState } from "react";

interface Erros {
  nome?: string;
  email?: string;
}

function FormCadastro() {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [erros, setErros] = useState<Erros>({});
  const [enviado, setEnviado] = useState(false);

  function validar(): boolean {
    const novos: Erros = {};
    if (nome.trim().length < 3) novos.nome = "Minimo de 3 letras";
    if (!email.includes("@")) novos.email = "E-mail invalido";
    setErros(novos);
    return Object.keys(novos).length === 0;   // sem erros?
  }

  function enviar() {
    if (!validar()) return;
    // aqui entraria o envio para uma API
    setEnviado(true);
  }

  if (enviado) return <p>Cadastro realizado!</p>;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();   // nao recarrega a pagina
        enviar();
      }}
      noValidate
    >
      <input value={nome} onChange={(e) => setNome(e.target.value)} />
      {erros.nome && <span className="erro">{erros.nome}</span>}

      <input value={email} onChange={(e) => setEmail(e.target.value)} />
      {erros.email && <span className="erro">{erros.email}</span>}

      <button type="submit">Cadastrar</button>
    </form>
  );
}

import { useState, useEffect } from "react";

function Contador() {
  const [contagem, setContagem] = useState(0);

  useEffect(() => {
    document.title = `Cliques: ${contagem}`;
  }, [contagem]);

  return (
    <button onClick={() => setContagem(contagem + 1)}>
      Cliquei {contagem} vezes
    </button>
  );
}

import { useState, useEffect } from "react";

function Relogio() {
  const [hora, setHora] = useState(new Date());

  useEffect(() => {
    const id = setInterval(() => setHora(new Date()), 1000);
    return () => clearInterval(id);   // limpeza: para o timer
  }, []);

  return <p>{hora.toLocaleTimeString()}</p>;
}

import { useState, useEffect } from "react";

interface Post {
  id: number;
  title: string;
}

function ListaPosts() {
  const [posts, setPosts] = useState<Post[]>([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState<string | null>(null);

  useEffect(() => {
    const controle = new AbortController();

    async function buscar() {
      try {
        const url = "https://jsonplaceholder.typicode.com/posts?_limit=5";
        const res = await fetch(url, { signal: controle.signal });
        if (!res.ok) throw new Error(`Erro ${res.status}`);
        setPosts(await res.json());
      } catch (e) {
        if (controle.signal.aborted) return;   // cancelada de proposito
        setErro(e instanceof Error ? e.message : "Erro desconhecido");
      } finally {
        if (!controle.signal.aborted) setCarregando(false);
      }
    }

    buscar();
    return () => controle.abort();   // limpeza: cancela a busca
  }, []);

  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p>Erro: {erro}</p>;

  return (
    <ul>
      {posts.map((p) => <li key={p.id}>{p.title}</li>)}
    </ul>
  );
}

import { useState, useRef, useEffect } from "react";

// 1. Referencia a um elemento do DOM
function CampoBusca() {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();   // coloca o cursor no campo
  }, []);

  return <input ref={inputRef} placeholder="Buscar..." />;
}

// 2. Valor guardado sem redesenhar a tela
function Cronometro() {
  const [segundos, setSegundos] = useState(0);
  const timerRef = useRef<number | null>(null);

  function iniciar() {
    if (timerRef.current !== null) return;   // ja esta rodando
    timerRef.current = window.setInterval(() => {
      setSegundos((s) => s + 1);
    }, 1000);
  }

  function pausar() {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }

  return (
    <div>
      <p>{segundos}s</p>
      <button onClick={iniciar}>Iniciar</button>
      <button onClick={pausar}>Pausar</button>
    </div>
  );
}

import { useState, useMemo, useCallback } from "react";

interface Produto {
  id: number;
  nome: string;
}

function Catalogo({ produtos }: { produtos: Produto[] }) {
  const [busca, setBusca] = useState("");
  const [tema, setTema] = useState("claro");

  // so refaz o filtro quando produtos ou busca mudam;
  // trocar o tema NAO refaz o filtro
  const filtrados = useMemo(
    () =>
      produtos.filter((p) =>
        p.nome.toLowerCase().includes(busca.toLowerCase())
      ),
    [produtos, busca]
  );

  // a mesma funcao em todas as renderizacoes
  const limpar = useCallback(() => setBusca(""), []);

  return (
    <div className={tema}>
      <input value={busca} onChange={(e) => setBusca(e.target.value)} />
      <button onClick={limpar}>Limpar</button>
      <button onClick={() => setTema(tema === "claro" ? "escuro" : "claro")}>
        Trocar tema
      </button>
      <ul>
        {filtrados.map((p) => <li key={p.id}>{p.nome}</li>)}
      </ul>
    </div>
  );
}

import { createContext, useContext, useState, type ReactNode } from "react";

// 1. O formato do que o contexto oferece
interface TemaContexto {
  tema: "claro" | "escuro";
  alternarTema: () => void;
}

// 2. Criar o contexto (undefined = fora do Provider)
const TemaCtx = createContext<TemaContexto | undefined>(undefined);

// 3. Provider: envolve a parte da arvore que usa o tema
export function TemaProvider({ children }: { children: ReactNode }) {
  const [tema, setTema] = useState<"claro" | "escuro">("claro");

  function alternarTema() {
    setTema((t) => (t === "claro" ? "escuro" : "claro"));
  }

  return (
    <TemaCtx value={{ tema, alternarTema }}>
      {children}
    </TemaCtx>
  );
}

// 4. Hook para ler o contexto, com aviso de uso errado
export function useTema() {
  const ctx = useContext(TemaCtx);
  if (!ctx) throw new Error("useTema precisa estar dentro do TemaProvider");
  return ctx;
}

// 5. Qualquer componente dentro do Provider pode usar
function BotaoTema() {
  const { tema, alternarTema } = useTema();
  return <button onClick={alternarTema}>Tema atual: {tema}</button>;
}

// 6. No App: o Provider envolve tudo
function App() {
  return (
    <TemaProvider>
      <BotaoTema />
    </TemaProvider>
  );
}

import { useState, useEffect } from "react";

// Guarda o valor no estado E no localStorage do navegador
function useLocalStorage<T>(chave: string, inicial: T) {
  const [valor, setValor] = useState<T>(() => {
    try {
      const salvo = localStorage.getItem(chave);
      return salvo ? (JSON.parse(salvo) as T) : inicial;
    } catch {
      return inicial;
    }
  });

  function salvar(novo: T) {
    setValor(novo);
    localStorage.setItem(chave, JSON.stringify(novo));
  }

  return [valor, salvar] as const;
}

// A busca da secao 3.10, agora reutilizavel
function useFetch<T>(url: string) {
  const [dados, setDados] = useState<T | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState<string | null>(null);

  useEffect(() => {
    const controle = new AbortController();
    fetch(url, { signal: controle.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<T>;
      })
      .then((d) => setDados(d))
      .catch((e) => {
        if (!controle.signal.aborted) setErro(e.message);
      })
      .finally(() => {
        if (!controle.signal.aborted) setCarregando(false);
      });
    return () => controle.abort();
  }, [url]);

  return { dados, carregando, erro };
}

function Painel() {
  const [tema, setTema] = useLocalStorage("tema", "claro");
  const { dados: posts, carregando, erro } = useFetch<Post[]>(
    "https://jsonplaceholder.typicode.com/posts?_limit=5"
  );

  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p>Erro: {erro}</p>;

  return (
    <div className={tema}>
      <button onClick={() => setTema(tema === "claro" ? "escuro" : "claro")}>
        Tema: {tema}
      </button>
      <ul>
        {posts?.map((p) => <li key={p.id}>{p.title}</li>)}
      </ul>
    </div>
  );
}
